"""Beginner explanations of section maps, sparse ranges and remote opens."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS = {
'os469': (
 '한 이야기가 여러 권에 나뉘어 있습니다. 앞 권이 10쪽이고 뒷 권의 보관 위치가 200번부터라면, 이야기 전체에서 14번인 쪽은 뒷 권 안에서 4번 떨어진 곳입니다. 번호는 0부터 센다고 해 보세요.',
 'ISOFS는 CD 같은 광학 매체의 ISO9660 형식을 읽는 파일시스템입니다. 한 파일이 여러 구간에 나뉘었을 때 각 구간의 실제 저장 위치를 계산합니다.',
 '파일의 앞 구간을 0~9번, 다음 구간을 10번부터라고 적으세요. 다음 구간의 장치 시작은 200입니다. 파일 블록 14까지의 거리 14-10을 구한 뒤 200에 더하세요. 다섯 블록을 부탁하고 두 개만 얻은 경우도 따로 표시하세요.',
 ['block은 데이터를 일정 크기로 묶은 단위입니다. 파일 안에서 센 번호를 논리 블록 번호, 저장장치에서 센 위치를 물리 블록 번호라고 합니다. 두 번호는 서로 다를 수 있습니다.',
  'section은 파일을 나눈 한 구간입니다. firstext는 현재 구간의 실제 시작 위치입니다. offset은 현재 구간에 오기 전에 지나온 구간들의 블록 수입니다. b_off는 찾으려는 파일 블록 번호입니다.',
  '공식 firstext+b_off-offset은 실제 시작 위치에 현재 구간 안의 거리를 더합니다. firstext=200, b_off=14, offset=10이면 먼저 14-10=4, 이어 200+4=204입니다. 200+14로 계산하면 앞 구간 10개를 중복해 셉니다.',
  '다음 구간이 있고 찾는 번호가 현재 구간 끝에 도달했으면 다음 구간 정보를 읽습니다. 지나온 크기를 offset에 더하고 firstext와 구간 크기도 새 값으로 바꿉니다. 계속 첫 구간의 시작 위치를 사용하면 다른 곳을 찾게 됩니다.',
  'rv는 지금까지 위치 연결에 성공한 블록 수입니다. 하나 성공할 때마다 rv++로 1을 더합니다. 마지막 return의 rv != 0 ? rv : error는 성공 수가 0이 아니면 그 수, 아니면 오류값을 돌려준다는 뜻입니다.',
  '다섯 블록을 요청했는데 두 개를 얻은 뒤 실패하면 2를 돌려줄 수 있습니다. 호출한 쪽은 2개만 준비됐음을 알아야 합니다. 양수라고 다섯 개 모두 준비됐다고 판단하면 안 됩니다. 이 함수의 위치 연결 성공이 파일 내용 전체를 이미 읽었다는 뜻도 아닙니다.',
  '구간을 따라갈 때 ++section으로 센 값이 100을 넘으면 중단합니다. 잘못된 연결을 끝없이 따라가지 않게 하는 제한입니다. 파일 크기가 100바이트라는 뜻은 아닙니다.'],
 [('현재 구간은 파일의 10번 블록부터이고, 장치에서는 200번부터 시작합니다. 파일의 14번 블록은 장치의 몇 번인가요?', ['214번이에요','204번이에요'], '204번입니다. 이 구간 안의 거리는 14-10=4입니다. 실제 시작 200에 그 거리만 더하면 200+4=204입니다. 214는 앞 구간의 10개를 빼지 않은 계산입니다.'),
  ('다섯 블록을 요청했는데 두 개를 준비한 뒤 실패했습니다. rv가 2이고 마지막 식은 rv!=0 ? rv : error입니다. 무엇을 돌려줄 수 있나요?', ['성공한 개수인 2를 돌려줘요','성공한 것이 있어도 반드시 음수 오류만 돌려줘요'], '2를 돌려줍니다. rv!=0이 참이므로 ? 뒤의 rv를 선택합니다. 이는 부분 성공입니다. 두 개 성공과 다섯 개 전체 성공을 구별해야 나머지 세 개를 잘못 사용하지 않습니다.')]),
'os470': (
 '연속한 좌석 열의 시작 번호와 좌석 수를 적어 두면 모든 좌석 번호를 하나씩 적을 필요가 없습니다. JFS의 extent도 이어진 저장 구간을 시작과 길이로 나타냅니다.',
 'JFS의 xtLookup은 파일 안의 구간을 실제 저장 위치와 길이로 바꿉니다. 저장 공간이 배정되지 않은 빈 구간도 검색 결과로 표현할 수 있습니다.',
 '파일 블록 20~29 아래에 장치 블록 500~509를 나란히 적으세요. 파일 24 아래의 번호를 찾고 24~29의 칸 수를 세세요. 요청 길이 20과 비교해 작은 수를 고르세요.',
 ['extent는 연속한 블록들의 묶음입니다. offset은 파일 안에서 묶음이 시작하는 번호, length는 묶음의 길이, physical start는 장치의 실제 시작 번호입니다. 이 수업의 계산 단위는 바이트가 아니라 블록입니다.',
  '파일 시작 20, 길이 10인 묶음은 20~29를 담습니다. 끝 바로 다음 번호는 20+10=30입니다. 블록 30 자체는 이 묶음에 없습니다. 시작 번호와 개수를 더한 값이 끝 다음 번호라는 점을 기억하세요.',
  '파일 블록 24는 시작 20에서 4칸 떨어져 있습니다. 장치 시작이 500이면 500+(24-20)=504입니다. 파일 번호 24를 그대로 500에 더하면 이미 지나온 앞부분까지 더하게 됩니다.',
  '24부터 이 묶음의 끝까지는 24,25,26,27,28,29의 여섯 블록입니다. 코드도 30-24=6으로 구합니다. min은 두 수 중 작은 수를 고르는 연산입니다. 20개를 요청해도 이 묶음 안에서 돌려줄 길이는 min(6,20)=6입니다.',
  'hole은 파일의 논리적 범위 중 실제 저장 블록이 배정되지 않은 구간입니다. 빈 부분까지 모두 디스크 공간을 쓰지 않고 표현할 때 사용합니다. 이 검색 함수는 출력 주소 paddr를 처음에 0으로 두고, 해당 구간이 hole이면 그대로 둘 수 있습니다.',
  '함수의 반환값 rc와 출력 주소 paddr는 다른 정보입니다. rc=0은 검색 처리에 오류가 없다는 뜻일 수 있고, paddr=0은 이 경로에서 실제 위치가 없음을 나타낼 수 있습니다. 주소 0을 보았다고 무조건 음수 오류라고 판단하지 않습니다. 파일 끝을 넘은 검색도 따로 확인해야 하므로 0인 주소만으로 모든 경우를 hole이라고 단정하지도 않습니다.',
  '다음 extent가 있으면 hole의 길이는 그 시작 앞까지만으로 제한할 수 있습니다. 사용한 관리 정보 페이지는 XT_PUTPAGE로 놓아줍니다. 위치를 찾는 이 작업만으로 파일 쓰기나 영구 저장 완료까지 보장되지는 않습니다.'],
 [('파일 블록 20~29가 장치 500~509에 있습니다. 파일 24부터 20개를 요청하면 이 묶음 안에서 돌려줄 시작 위치와 길이는?', ['위치 524, 길이 20이에요','위치 504, 길이 6이에요'], '위치 504, 길이 6입니다. 거리 24-20=4를 500에 더합니다. 끝 다음 번호 30에서 24를 빼면 남은 길이 6입니다. 요청한 20보다 작으므로 이번 묶음에서는 여섯 개까지만 연결합니다.'),
  ('실제 저장 공간이 없는 hole 구간을 찾았습니다. 함수 반환값은 0이고 출력 주소도 0입니다. 반드시 검색 오류인가요?', ['아니요. 빈 구간을 정상적으로 표현한 결과일 수 있어요','네. 출력 주소 0은 언제나 음수 오류예요'], '빈 구간의 정상 결과일 수 있습니다. 주소를 담는 paddr와 오류 여부를 돌려주는 rc를 구별해야 합니다. 이 경로는 주소를 0으로 유지한 채 rc=0으로 끝날 수 있습니다. 실제 장치 0번을 읽으라는 뜻으로 바꾸면 안 됩니다.')]),
'os471': (
 '멀리 있는 자료실에서 책을 빌리려면 이용 자격을 확인하고 대출 기록을 준비합니다. 준비가 실패하면 만들던 기록을 정리하고 실패를 알립니다.',
 'AFS는 네트워크를 통해 파일을 사용하는 파일시스템입니다. afs_open은 사용할 자격 정보와 이번 열기에 필요한 상태를 준비하고, 모두 준비된 뒤 성공을 알립니다.',
 'key 요청 → 열기 기록 af 준비 → 파일 상태 검사 → 쓰기라면 writeback key 준비 → private_data에 연결을 그리세요. 쓰기 준비 실패에서는 af 해제 → key 참조 반납 → 오류 반환으로 빠지게 하세요.',
 ['cell은 AFS의 관리 영역입니다. volume은 그 안의 파일 묶음이고 vnode는 파일을 나타내는 커널 객체입니다. afs_request_key는 그 cell에 맞는 key를 요청합니다. 여기 key는 키보드 키가 아니라 접근에 쓰는 자격 정보와 관련된 객체입니다.',
  'IS_ERR(key)는 결과가 정상 key가 아니라 오류를 담은 값인지 검사합니다. PTR_ERR(key)는 그 안의 오류 번호를 꺼냅니다. 요청 실패라면 ret에 그 번호를 넣고 실패로 끝납니다. 아무 key 없이 성공으로 바꾸지 않습니다.',
  'af는 이번에 연 파일을 위한 기록입니다. kzalloc으로 그 기록을 위한 메모리를 준비하고 key를 연결합니다. vnode와 key와 af는 역할이 다릅니다. 같은 파일을 여러 번 여는 경우에도 파일 객체와 각 열기 기록을 구별해야 합니다.',
  'afs_validate는 vnode의 상태를 key와 함께 검사합니다. 메모리에 전에 읽은 자료가 남아 있는 것만으로 서버의 현재 상태와 이용 조건이 언제까지나 맞는 것은 아닙니다. 캐시는 전에 얻은 내용을 가까이 보관해 다시 사용하는 공간입니다.',
  '쓰기 모드이면 afs_cache_wb_key로 writeback에 쓸 key를 준비합니다. writeback은 바뀐 내용을 나중에 저장 쪽으로 보내는 작업입니다. 준비 함수의 ret가 음수면 error_af로 이동합니다.',
  'error_af에서는 kfree(af)로 이번 기록의 메모리를 해제하고, 이어 key_put(key)로 잡고 있던 key 참조를 놓습니다. 참조를 놓는다는 것은 이번 사용을 끝낸다는 뜻입니다. 다른 사용자도 가진 key 자체를 언제나 즉시 없앤다는 뜻은 아닙니다.',
  '성공 경로는 캐시 사용을 시작한 뒤 file->private_data=af로 이번 열기의 기록을 연결하고 0을 반환합니다. 필요한 준비가 실패한 경로에서는 이 성공 연결까지 도달하지 않습니다. 반환값이 음수인지와 성공 기록이 연결되는 순서를 함께 보세요.'],
 [('afs_request_key의 결과가 오류라고 IS_ERR가 알려 줍니다. 이 afs_open은 어떻게 하나요?', ['key를 확인하지 않고 항상 성공해요','PTR_ERR로 오류 번호를 꺼내 실패를 알려요'], '두 번째입니다. ret=PTR_ERR(key) 다음 goto error로 가서 ret를 반환합니다. 아직 af 기록을 만들기 전이므로 성공 상태를 연결하지 않습니다. 이전에 캐시한 파일이 있다고 이 오류를 무시하지 않습니다.'),
  ('쓰기 위해 파일을 여는 중 writeback key 준비가 실패했습니다. 이미 만든 af 기록과 key 참조는 어떻게 하나요?', ['af를 해제하고 key 참조를 놓은 뒤 실패를 알려요','준비가 덜 된 af를 성공 기록으로 연결해요'], 'error_af에서 kfree(af), 다음 error_key에서 key_put(key)를 실행하고 오류를 반환합니다. 성공 경로의 private_data 연결을 건너뜁니다. 준비하던 물건을 정리하고 실패를 알리는 순서입니다.')]),
'os472': (
 '도서관의 책 등록 번호와 집에 빌려 온 책은 다릅니다. 등록 번호로 책을 요청한 뒤 실제 받은 책이 있어야 읽기를 시작할 수 있습니다.',
 'Coda는 원격 파일을 다루면서 로컬 파일을 통해 내용을 사용하는 파일시스템입니다. 커널은 Venus라는 사용자 공간 프로그램에 도움을 요청하고, 실제 사용할 파일을 받았는지도 확인합니다.',
 'CodaFid라는 파일 식별표 → venus_open 요청 → 로컬 host_file 받기 → container에 보관을 그리세요. host_file이 NULL이면 -EIO와 기록 해제로 이어지는 가지를 그리세요.',
 ['분산 파일시스템은 여러 컴퓨터와 통신하며 파일을 다룹니다. CodaFid는 Coda 쪽 파일을 식별하는 정보입니다. 식별 정보는 어느 파일을 원하는지 말해 주지만 그 자체가 내용을 읽을 열린 로컬 파일은 아닙니다.',
  'Venus는 사용자 공간에서 동작하는 Coda의 캐시 관리 프로그램입니다. upcall은 커널이 이 프로그램 쪽에 일을 요청하는 통신입니다. 이 open 경로는 커널 코드만으로 모든 일을 끝내지 않고 venus_open에 요청합니다.',
  'host_file은 반환받을 로컬 파일 객체입니다. 처음 NULL은 아직 받은 파일이 없다는 표시입니다. &host_file은 결과를 여기에 담도록 변수의 위치를 넘기는 C 표현입니다. 코드에서는 숫자 파일 번호 대신 struct file 포인터로 다룹니다.',
  'venus_open이 돌려준 오류 번호뿐 아니라 host_file도 검사합니다. !host_file은 파일이 없다는 뜻입니다. 이 경우 error=-EIO로 바꿉니다. EIO는 입출력 오류를 나타냅니다. 오류 번호가 처음 0이었어도 필요한 파일을 받지 못했다면 성공하지 않습니다.',
  'cfi는 이번 열기에 필요한 기록입니다. 오류가 있으면 kfree(cfi)로 메모리를 정리하고 오류를 반환합니다. 성공하면 cfi_container에 host_file을 보관하고 private_data에 cfi를 연결합니다.',
  '따라서 CodaFid와 cfi_container는 서로 연결되는 정보지만 같은 물건은 아닙니다. 앞의 것은 원격 파일을 구별하는 식별 정보, 뒤의 것은 내용을 다루는 로컬 열린 파일을 가리킵니다. 같은 포인터라고 바꾸어 사용하면 역할을 혼동하게 됩니다.',
  'O_APPEND는 끝에 덧붙이기, O_SYNC는 쓰기의 동기 완료와 관련된 표시입니다. 성공 경로는 이 표시들을 host_file에도 반영합니다. 전달할 옵션은 Coda 표현으로 바꾸며 O_EXCL은 이 전달에서 뺍니다. 여기서 모든 옵션의 숫자를 그대로 복사하는 것은 아닙니다.'],
 [('venus_open의 오류 번호는 0이지만 host_file은 NULL입니다. 필요한 로컬 파일을 받지 못한 이 open은 어떻게 되나요?', ['빈 container로 성공해요','-EIO 오류로 실패해요'], '-EIO로 실패합니다. if (!host_file)에서 error=-EIO로 바꾼 다음, 오류 처리에서 cfi를 해제하고 반환합니다. 오류 번호와 실제 필요한 자원의 존재를 둘 다 확인합니다.'),
  ('CodaFid와 cfi_container를 어떻게 구별하면 좋을까요?', ['분산 파일의 식별 정보와 로컬 열린 파일을 가리키는 정보예요','두 이름은 언제나 같은 커널 포인터예요'], '첫 번째입니다. CodaFid로 원하는 대상을 요청하고, 받은 host_file을 cfi_container에 넣습니다. 책의 등록 번호와 빌려 온 책을 나누어 생각해 보세요. 요청 대상을 식별하는 일과 실제 읽을 자원을 갖는 일은 연결되지만 다릅니다.')]),
}

def run():
    additions = {}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key = lesson['id']
            if key not in ROWS:
                continue
            practice = dict(lesson.get('practice', {}))
            practice['expected'] = ROWS[key][2]
            additions[key] = dict(concepts=[], reading_support=None, deep_dive=[],
                goal='저장 위치 계산과 원격 파일을 열 때 성공·실패하는 순서를 예제로 설명해 보세요.',
                experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]}, practice=practice)
    return rewrite(ROWS, 'tools/rewrite_os_beginner_113.py', additions)

if __name__ == '__main__':
    print(json.dumps(run(), ensure_ascii=False))
